from pathlib import Path
from playwright.sync_api import sync_playwright
import hashlib,json
ROOT=Path(__file__).resolve().parents[1];source=(ROOT/'assets/game.js').read_bytes();sha=hashlib.sha256(source).hexdigest()
probe='''window.__queueTest={ready:()=>saveStorePromise,flush:async()=>{await saveStorePromise;await saveWrites},hold:()=>{window.__writeCalls=0;const original=writeIndexedDB;let release;const gate=new Promise(r=>release=r);window.__releaseWrite=release;writeIndexedDB=async(e,epoch)=>{window.__writeCalls++;if(window.__writeCalls===1)await gate;return original(e,epoch)};},save:()=>save(),state:()=>({order:saveOrder,revision:saveRevision,ok:autoSaveOK,pending:!!savePendingWrite,active:saveWriteRunning}),large:()=>{const g=JSON.parse(archivePayload());while(g.people.length<8000)g.people.push({id:g.people.length,name:'Historical resident '+g.people.length,age:90,hh:0,job:-1,health:0,skill:.5,life:0,last:[],deceased:true});if(!hydrateSave(g))throw Error('Large history rejected');return new Blob([archivePayload()]).size}};'''
script=source.decode().replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js')
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.route('**/game.js',lambda r:r.fulfill(body=script,content_type='application/javascript'));p.goto((ROOT/'assets/index.html').as_uri());p.evaluate('__queueTest.ready()');p.locator('#newTown').click();p.locator('#pause').click();p.evaluate('__queueTest.flush()');payloadBytes=p.evaluate('__queueTest.large()');p.evaluate('__queueTest.save()');p.evaluate('__queueTest.flush()');p.locator('[data-panel=settings]').click();p.evaluate('__queueTest.hold();document.querySelector("#saveNow").click()');p.wait_for_function('__writeCalls===1');p.evaluate('for(let i=0;i<40;i++)document.querySelector("#saveNow").click()');assert p.locator('#saveNow').is_disabled();p.evaluate('for(let i=0;i<40;i++)__queueTest.save();void 0');p.evaluate('__releaseWrite()');p.evaluate('__queueTest.flush()');calls=p.evaluate('__writeCalls');assert calls<=2,{'indexedWritesFor41Clicks':calls};assert p.evaluate('__queueTest.state().ok');assert not p.locator('#saveNow').is_disabled();assert p.evaluate('__townTest.validate().ok');b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==sha
out=ROOT/'reports/development-persistence';out.mkdir(exist_ok=True);(out/'queue.json').write_text(json.dumps({'source_sha256':sha,'saveClickAttempts':41,'acceptedUIClicks':1,'directBurstRequests':40,'historyPeople':8000,'payloadBytes':payloadBytes,'indexedWrites':calls},indent=2)+'\n');print('PASS 41 Save click attempts (one accepted while busy),40 direct requests, bounded snapshot queue;',calls,'indexed writes')
